-- Полные тексты, анонсы и оригинальные изображения 18 материалов ivs-corp.ru.
-- Импорт выполнен scripts/import-news.py; применять после 0001_news.sql.

alter table news add column if not exists excerpt text not null default '';
alter table news add column if not exists content_html text not null default '';

update news set excerpt = 'В пятницу 17 апреля ЗАО "ИВС-СЕТИ" совместно с партнёрами по информационной безопасности UserGate и автосалоном "Демидыч" организовали и провели автоквест "КИБЕРПАТРУЛЬ" для заказчиков.', content_html = '<p>В пятницу 17 апреля ЗАО "ИВС-СЕТИ" совместно с партнёрами по информационной безопасности UserGate и автосалоном "Демидыч" организовали и провели автоквест "КИБЕРПАТРУЛЬ" для заказчиков.</p><p>Заброшенные дома Кировского района и сюрпризы в заданиях от организаторов постоянно держали в тонусе и не давали расслабиться всем участникам автоквеста. А китайские автомобили добавляли динамику, скорость, драйв и позитив всему происходящему. Все почувствовали себя агентами 007.</p><p>Выдохнуть удалось только вечером при подведении итогов и проведении квиза по информационной безопасности от UserGate. В автоквесте "КИБЕРПАТРУЛЬ" никто не пострадал, все остались довольны и счастливы!</p>', image_url = '/news/articles/kiberpatrul-v-dele/01.jpg' where slug = 'kiberpatrul-v-dele';

update news set excerpt = 'Дорогие друзья! Поздравляем вас с наступающим Новым годом! Благодарим за доверие и продуктивное сотрудничество в уходящем году.', content_html = '<p>Дорогие друзья!</p><p>Поздравляем вас с наступающим Новым годом! Благодарим за доверие и продуктивное сотрудничество в уходящем году.</p><p>Желаем, чтобы 2026-й год принес множество выгодных предложений и возможностей вашему бизнесу. Процветания, стабильности и покорения новых высот.  Пусть Новый год станет временем реализации самых смелых проектов и финансового успеха.</p><p>Мира, благополучия и крепкого здоровья вам и вашим близким.</p><p>Команда ЗАО "ИВС-СЕТИ"</p>', image_url = '/news/articles/s-novym-godom/01.jpg' where slug = 's-novym-godom';

update news set excerpt = 'В рамках программы импортозамещения компания РЕД СОФТ совместно с Минсвязи Пермского края реализует проект по переходу ИТ‑инфраструктуры региональных органов исполнительной власти Пермского края на российское…', content_html = '<p>В рамках программы импортозамещения компания РЕД СОФТ совместно с Минсвязи Пермского края реализует проект по переходу ИТ‑инфраструктуры региональных органов исполнительной власти Пермского края на российское программное обеспечение. В реализации проекта также участвуют компании ИТ‑Групп и ИВС-Сети.</p><p>⚡️ Операционная система РЕД ОС обеспечивает совместимость с используемыми в Пермском крае российскими программными продуктами, такими как Консультант, АЦК от БФТ, а также со средствами защиты информации и системами электронного документооборота.</p><p><em>«Пермский край с 2019 года осуществляет планомерный переход на отечественное офисное и защитное программное обеспечение, а также операционные системы. Такой подход не только <br/>
 позволяет решать задачи национального проекта "Экономика данных“, но и демонстрирует эффективность отечественных решений на собственном примере. В настоящее время на <br/>
 автоматизированных рабочих местах сотрудников органов власти, подведомственных организаций и в Центре обработки данных Правительства Прикамья используются исключительно <br/>
 сертифицированные российские средства защиты информации. Данная работа ведётся в сотрудничестве с ИТ‑компаниями, включая РЕД СОФТ, ИВС-Сети и ИТ‑Групп», — <strong>сообщил министр информационного развития и связи Пермского края Петр Шиловских.</strong></em></p><p>Проект реализуется поэтапно, чтобы обеспечить переход на отечественное программное обеспечение без нарушения работы государственных учреждений и предприятий Пермского края. Всего реализовано пять этапов внедрения: аудит и планирование, пилотное тестирование, обучение персонала, миграция, поддержка и сопровождение. На каждом этапе проводится анализ результатов, корректируются планы миграции и вносятся необходимые изменения, что позволяет минимизировать риски и гарантировать успешную реализацию проекта.</p><p>✅ Так, при реализации проекта в образовательные организации безвозмездно передано более 70 тысяч лицензий. Кроме того, на данный момент оснащено более 20 тысяч рабочих мест в различных органах власти и подведомственных организациях Прикамья. Работа по внедрению отечественного ПО продолжается.</p><p>Проект импортозамещения ИТ-инфраструктуры станет основой для укрепления цифрового суверенитета региона.</p><p>⛓ <a href="https://clck.ru/3Qtviz" rel="noopener noreferrer" target="_blank">Читайте подробности</a></p>' where slug = 'permskiy-kray-perekhodit-na-otechestvennuyu-operatsionnuyu-sistemu-red-os';

update news set excerpt = 'В издании об ИТ-бизнесе для ИТ-бизнесменов IT Channel News опубликованы новость и фоторепортаж о прошедшем 3 апреля Межрегиональном Цифровом Форуме. Подробнее в новости и фоторепортаже', content_html = '<p>
	 В издании об ИТ-бизнесе для ИТ-бизнесменов IT Channel News опубликованы новость и фоторепортаж о прошедшем 3 апреля Межрегиональном Цифровом Форуме.  
</p>
<p>
	 Подробнее в <a href="https://www.novostiitkanala.ru/news/detail.php?ID=187725" rel="noopener noreferrer" target="_blank">новости</a> и <a href="https://www.novostiitkanala.ru/foto/detail.php?ID=187746" rel="noopener noreferrer" target="_blank">фоторепортаже</a>
</p>', image_url = '/news/articles/it-channel-news-opublikoval-novost-i-fotoreportazh-o-mezhregionalnom-tsifrovom-forume/01.jpg' where slug = 'it-channel-news-opublikoval-novost-i-fotoreportazh-o-mezhregionalnom-tsifrovom-forume';

update news set excerpt = 'Партийный проект «Цифровая Россия» при поддержке Минсвязи Пермского края, фонда «Цифровая долина Прикамья» и ИТ-компании ИВС проведет ИТ-форум, посвященный импортозамещению и достижению технологической независимости.', content_html = '<p>
	 Партийный проект «Цифровая Россия» при поддержке Минсвязи Пермского края, фонда «Цифровая долина Прикамья» и ИТ-компании ИВС проведет ИТ-форум, посвященный импортозамещению и достижению технологической независимости.
</p>
<p>
	 Форум пройдет 3 апреля 2025 года на площадке «Пермь ЭКСПО». Участие в мероприятии примут свыше 500 отраслевых экспертов из государственного сектора, ИТ-бизнеса и профильных некоммерческих организаций.
</p>
<p>
	 На площадке форума будет работать несколько тематических секций. Пленарное заседание будет посвящено достижению технологической независимости, где бизнес и власть обсудят актуальные вопросы и вызовы, стоящие перед Россией в вопросе достижения цифрового суверенитета. Участники представят результаты программ по ИТ-импортозамещению в государственном и корпоративном секторах и обсудят эффективность текущих механизмов поддержки инновационных продуктов в сфере ИТ.
</p>
<p>
	 Помимо этого, будут рассмотрены примеры успешных проектов и инициатив, направленных на снижение зависимости от импорта технологий и материалов. Цель пленарной дискуссии – формирование рекомендаций для корректировки стратегий ИТ-импортозамещения в бизнесе и государственном секторе.  
</p>
<p>
	 Помимо пленарной дискуссии пройдут профильные круглые столы, посвященные отдельным аспектам внедрения и популяризации российских технологий. В повестке форума также – заседание экспертного совета по противодействию идеологии терроризма при антитеррористической комиссии в Пермском крае. Участники заседания обсудят новые подходы в профилактике терроризма, включая образовательные инициативы и социальные проекты, направленные, прежде всего, на молодых людей.
</p>
<p>
	 На площадке форума пройдет выставка ИТ-решений, на которой участники мероприятия смогут ознакомиться с передовыми разработками в области информационных технологий. В демо-зале производителей ИТ-оборудования будут представлены новейшие устройства и системы, способствующие оптимизации бизнес-процессов. Демо-зал производителей программного обеспечения и решений в сфере информационной безопасности предложит посетителям ознакомиться с актуальными программными продуктами, гарантирующими защиту данных и предотвращение угроз. В демо-зале производителей инженерных решений участники смогут познакомиться с отечественными инновациями в сфере инженерии, включая системы автоматизации и управления.
</p>
<p>
	 Среди вендоров-участников форума: Аквариус, Yadro, Systeme Electric, User Gate, Код Безопасности, «Лаборатория Касперского», VK tech и Positive Technologies.
</p>
<p>
	 Форум станет уникальной экспертной площадкой по обмену опытом и лучшими кейсами внедрения российских технологий, отмечает депутат Госдумы, член комитета по информполитике и федеральный координатор партийного проекта «Цифровая Россия» Антон Немкин. «Перед ИТ-отраслью сегодня стоят стратегические задачи по импортозамещению, часть из них уже выполнена. Высокая доля основных программных продуктов, к примеру, уже импортозамещена, более 50% серверного оборудования в настоящий момент занимают отечественные производители. Но далеко не во всех сегментах динамика внедрения отечественных технологий позитивна. Наша задача – выявить стоп-факторы и разработать пути решения возникших трудностей. В том числе за счет анализа регионального опыта и масштабирования лучших практик», – подчеркнул депутат.
</p>
<p>
	 По словам заместителя председателя Правительства Пермского края Алексея Черникова, форум станет платформой для диалога между государственными структурами и бизнесом, что крайне важно для внедрения современных ИТ-решений и повышения уровня цифровизации. Возможность обмена опытом и обсуждения успешных кейсов внедрения российских ИТ-продуктов позволит участникам не только узнать о лучших практиках, но и наладить полезные контакты.
</p>
<p>
	 «Особое внимание мы уделяем работе Центра обработки данных Правительства Пермского края, в серверном сегменте которого размещено более 50 государственных информационных систем региона, и информационной безопасности. Наработан обширный опыт, которым мы готовы поделиться с коллегами из соседних регионов», – отметил Алексей Черников.
</p>
<p>
	 «Единая Россия» запустила партийный проект «Цифровая Россия» в 2022 году для содействия цифровизации страны. В частности, проект направлен на поддержку представителей ИТ-сферы, обеспечение безопасности пользователей интернета, развитие цифровой валюты и поддержку российских цифровых сервисов.
</p>
<p>
	 Регистрация на Межрегиональный ИТ-форум открыта на сайте <a href="https://forumit.site/" rel="noopener noreferrer" target="_blank">https://forumit.site/</a>
</p>', image_url = '/news/articles/mezhregionalnyy-it-forum-provedut-v-prikame/01.jpg' where slug = 'mezhregionalnyy-it-forum-provedut-v-prikame';

update news set excerpt = 'ЗАО "ИВС-СЕТИ" в 14 раз стало победителем рейтинга «25 лучших региональных ИТ-компаний 2024» по мнению редакции IT Channel News и экспертных оценок представителей 40 компаний.', content_html = '<p>ЗАО "ИВС-СЕТИ" в 14 раз стало победителем рейтинга «25 лучших региональных ИТ-компаний 2024» по мнению редакции IT Channel News и экспертных оценок представителей 40 компаний.</p><p>Подробная информация на сайте <a href="https://www.novostiitkanala.ru/news/detail.php?ID=181372" rel="noopener noreferrer" target="_blank">IT Channel News</a></p>', image_url = '/news/articles/zao-ivs-seti-v-14-raz-stalo-pobeditelem-reytinga-25-luchshikh-regionalnykh-it-kompaniy-2024-po-mneni/01.jpg' where slug = 'zao-ivs-seti-v-14-raz-stalo-pobeditelem-reytinga-25-luchshikh-regionalnykh-it-kompaniy-2024-po-mneni';

update news set excerpt = '1 июня наша команда коллег-героев "ИВС" успешно преодолела многочисленные препятствия в экстремальном забеге "Стальной характер" на дистанции 5 км.', content_html = '<p>1 июня наша команда коллег-героев "ИВС" успешно преодолела многочисленные препятствия в экстремальном забеге "Стальной характер" на дистанции 5 км.<br/>
<br>
Поздравляем самых сильных и смелых коллег с преодолением этой величины! Молодцы! Так держать!<br/>
<br/>
Стоит отметить,  "СТАЛЬНОЙ ХАРАКТЕР" - это всероссийский мультиспортивный проект, призванный для формирования культуры здорового образа жизни, создания командного духа, В этом году проекту 10 лет. Участие в забеге доступно разным людям: спортивным и неспортивным, рискованным и осторожным, уверенным в себе и тем, кто только учится им быть. Препятствия забега сложны с психологической точки зрения, однако, с помощью участников команды их прохождение реально. Цель каждого участника – прохождение трассы, а не борьба и соревнование друг с другом.</p>', image_url = '/news/articles/iyunya-nasha-komanda-ivs-prinyala-uchastie-v-ekstremalnom-zabege-stalnoy-kharakter-na-distantsii-5-k/01.jpg' where slug = 'iyunya-nasha-komanda-ivs-prinyala-uchastie-v-ekstremalnom-zabege-stalnoy-kharakter-na-distantsii-5-k';

update news set excerpt = 'ЗАО "ИВС-СЕТИ" приняло участие в благотворительной акции Благотворительного Фонда "Источник Надежды", посвященной Дню защиты детей.', content_html = '<p>ЗАО "ИВС-СЕТИ" приняло участие в благотворительной акции Благотворительного Фонда "Источник Надежды", посвященной Дню защиты детей. В субботу весь мир отмечал этот праздник, призванный привлечь внимание людей к проблемам, с которыми сталкиваются дети на всей планете.<br/>
<br>
1 июня стартовала череда мероприятий для подопечных Фонда. Впереди целая насыщенная неделя детских мероприятий, где запланирован ещё выезд в парк аттракционов, квесты, мастер классы с аниматорами в больницах детей проходящих долгое лечении, посещение детского хосписа и катание на теплоходе деток с ОВЗ и их родителей. <br/>
<br/>
ЗАО "ИВС-СЕТИ" не первый год сотрудничает с Благотворительным Фондом "Источник Надежды" и таким образом помогает людям Перми и Пермского края, попавшим в сложные жизненные ситуации.<br/>
<br/>
Поздравляем всех детей и их родителей с этим чудесным Днём защиты детей!<br/>
</p>', image_url = '/news/articles/zao-ivs-seti-prinyalo-uchastie-v-blagotvoritelnoy-aktsii-blagotvoritelnogo-fonda-istochnik-nadezhdy/01.jpg' where slug = 'zao-ivs-seti-prinyalo-uchastie-v-blagotvoritelnoy-aktsii-blagotvoritelnogo-fonda-istochnik-nadezhdy';

update news set excerpt = 'В ходе мероприятия представители ИТ-отрасли обсудили вопросы оперативного и долгосрочного импортозамещения ключевых программных продуктов и оборудования, необходимых для работы промышленности и бизнеса.', content_html = '<p>
	В ходе мероприятия представители ИТ-отрасли обсудили вопросы оперативного и долгосрочного импортозамещения ключевых программных продуктов и оборудования, необходимых для работы промышленности и бизнеса.<br/>
</p>
<p>
	 Организатором форума выступил Фонд "Цифровая долина Прикамья", который ведет системную работу по аккумулированию и поддержке новых разработок ИТ-специалистов и компаний Пермского края.
</p>
<p>
	 В форуме приняли участие ИТ-представители более 40 предприятий края - это практически вся промышленность среднего и крупного уровня региона.
</p>
<p>
	 Промышленники, которые приняли участие в форуме “Новейшая цифровая среда”, с огромным интересом познакомились с новыми российскими ИТ-продуктами для промышленных предприятий и воспользовались нашими экспертными рекомендациями. Кроме того, для успешного и оперативного импортозамещения необходимо, чтобы процесс переговоров сопровождали эксперты-практики, как это было в нашем случае. Мы консультировали компании не по теоретическому анализу, а с точки зрения практического опыта работы с представленными программными продуктами. Принципиально важно и то, чтобы заказчики могли общаться друг с другом - делиться опытом использования российского ПО, отмечать особенности того или иного ИТ-продукта, задавать друг другу вопросы и предостерегать от потенциальных рисков.
</p>
<p>
	 Подробнее можно прочитать здесь:
</p>
<p>
<a href="https://www.kommersant.ru/doc/5899032" rel="noopener noreferrer" target="_blank">https://www.kommersant.ru/doc/5899032</a>
</p>
